import { notFound } from 'next/navigation';
import { Metadata } from 'next';
import { BackButton } from '../../../components/BackButton';

interface Post {
  userId: number;
  id: number;
  title: string;
  body: string;
}

interface Comment {
  postId: number;
  id: number;
  name: string;
  email: string;
  body: string;
}

export async function generateStaticParams() {
  const posts: Post[] = await fetch('https://jsonplaceholder.typicode.com/posts')
    .then((res) => res.json());

  return posts.slice(0, 10).map((post) => ({
    id: post.id.toString(),
  }));
}

export async function generateMetadata({ params }: { params: Promise<{ id: string }> }): Promise<Metadata> {
  const { id } = await params;
  // Use try-catch to handle potential errors during metadata generation
  try {
      const post: Post = await fetch(`https://jsonplaceholder.typicode.com/posts/${id}`).then((res) => {
          if (!res.ok) throw new Error('Failed to fetch post');
          return res.json();
      });

      return {
        title: `${post.title} - My Blog`,
        description: post.body.substring(0, 160),
        openGraph: {
          title: post.title,
          description: post.body.substring(0, 160),
        },
      };
  } catch (e) {
      return {
          title: 'Post Not Found',
      }
  }
}

async function getPost(id: string): Promise<Post | null> {
  const res = await fetch(`https://jsonplaceholder.typicode.com/posts/${id}`, {
    next: { revalidate: 300 },
  });
  if (!res.ok) return null;
  return res.json();
}

async function getComments(id: string): Promise<Comment[]> {
  const res = await fetch(`https://jsonplaceholder.typicode.com/posts/${id}/comments`, {
    next: { revalidate: 300 },
  });
  if (!res.ok) return [];
  return res.json();
}

export default async function BlogPost({ params }: { params: Promise<{ id: string }> }) {
  const { id } = await params;

  const [post, comments] = await Promise.all([
    getPost(id),
    getComments(id),
  ]);

  if (!post || !post.id) {
    notFound();
  }

  return (
    <article>
      <BackButton />

      <h1>{post.title}</h1>
      <p>{post.body}</p>

      <h2>Comments ({comments.length})</h2>
      <div className="comments">
        {comments.map((comment) => (
          <div key={comment.id} className="comment">
            <h3>{comment.name}</h3>
            <p>{comment.body}</p>
            <small>By: {comment.email}</small>
          </div>
        ))}
      </div>
    </article>
  );
}

